 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal bars have a one-cell gap whose column is aligned with a
    # vertical colored marker near the bottom. Extend/complete that column;
    # each horizontal bar colors the interval up to its row, and the marker
    # color fills the interval below the final bar.
    gaps = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            left, mid, right = row[c-1], row[c], row[c+1]
            if mid == 0 and left != 0 and right != 0:
                # The flanking horizontal segments provide this row's color.
                gaps.setdefault(c, []).append((r, left))
    for c, bars in gaps.items():
        bars.sort()
        # This column must have a vertical marker beneath the last bar.
        marker_rows = [r for r in range(h) if grid[r][c] != 0]
        marker_color = grid[marker_rows[-1]][c] if marker_rows else 0
        start = 0
        for r, color in bars:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
        if marker_color:
            for rr in range(start, h):
                out[rr][c] = marker_color
    return out
